    landingTail(current, fromX, fromY, targetX, targetY) {
      return behavior.landingTail(current, fromX, fromY, targetX, targetY);
    },

    finalized(current) {
      behavior.finalized(current);
    },

    reportError: behavior.reportError,

    retire() {
      behavior.retire();
