export function armCancelInput(
  realm: DOMRealm,
  cancelSignal: AbortSignal,
  onEscape: () => void,
): void {
  realm.document.addEventListener(
    KEY_DOWN,
    (event: KeyboardEvent) => {
      if (event.key === KEY_ESCAPE) {
        onEscape();
      }
    },
    { signal: cancelSignal },
  );
