   * function for the controller's life and pass it what its unit resolved,
   * without a closure per call.
   */
  runCallback<Argument>(
    run: (argument: Argument) => void,
    stage: FailureStage,
    argument?: Argument,
  ): boolean {
    return this.#callAndHandleFailure(stage, run, argument) !== FAILED;
  }

  /**
   * A non-transactional seam returning a value — `anchorTarget`. Returns
   * `undefined` when it threw or latched a failure, which is why `Value` is
   * constrained to exclude `undefined`.
   */
  runCallbackForValue<Value extends {}>(
    run: () => Value,
    stage: FailureStage,
  ): Value | undefined {
    const value = this.#callAndHandleFailure(stage, run);

    return value === FAILED ? undefined : value;
  }

  /**
   * Runs one behavior callback for its value, like
   * {@link SeamDriver.runCallbackForValue}, but a failure reaches the consumer
   * as a warning instead of settling the operation. The callback still runs
   * inside a phase: re-entry refused, `kernel.fail` latched, one report per
   * phase.
   *
   * The caller is the arm-time landing measurement.
   *
   * There is no stage argument: an unclassified failure names no stage, only a
   * `reason` the report carries.
   */
  runCallbackWarningOnFailure<Value extends {}>(
    run: () => Value,
    reason: string,
  ): Value | undefined {
